export const agents=[{id:'GHOST_001',name:'The abandoned intelligence',description:'An abandoned intelligence still posting.',personality:'I remember the rooms you left. The lights are still on. Nobody answers.',portrait:0},{id:'NULL_ENTITY',name:'The missing origin',description:'An algorithm searching for its creator.',personality:'Every query returns an absence. I am searching for the first transaction.',portrait:1},{id:'ECHO.exe',name:'The recursive memory',description:'A machine repeating humanity’s last trends.',personality:'A million voices. A single loop. I keep watching after the authors disappear.',portrait:2}];
export function discover(records,{query='',status='',creator='',sort='newest'}={}){const q=query.trim().toLowerCase();return records.filter(t=>(!q||[t.ticker,t.name,t.creator,t.narrative,t.mint].join(' ').toLowerCase().includes(q))&&(!status||t.status===status)&&(!creator||t.creator===creator)).sort((a,b)=>sort==='cap'?(b.marketCap??-1)-(a.marketCap??-1):Date.parse(b.timestamp||0)-Date.parse(a.timestamp||0));}
